INSERT INTO dbo.ChatMessages (Message_ID, Chat_Session_ID, Sender_Type, Content, Metadata_JSON, Created_At) VALUES
(10001, 10001, 'USER', N'Tăng cân khi ăn chay bằng cách nào?', NULL, DATEADD(MINUTE,-17040,@Now)),
(10002, 10001, 'ASSISTANT', N'Hãy tăng khẩu phần năng lượng bằng các món giàu đạm và chất béo tốt như đậu hũ chiên, tempeh, hạt, khoai lang, kết hợp tập luyện kháng lực và ăn thêm bữa phụ. Gợi ý thêm: Bánh Cuốn Chay; Canh Khoai Nấm.', N'{"sources":[{"type":"RECIPE","id":10114,"title":"Bánh Cuốn Chay – bản giữ cân"},{"type":"RECIPE","id":10035,"title":"Canh Khoai Nấm – bản giữ cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10114,"title":"Bánh Cuốn Chay – bản giữ cân","cookTimeMinutes":32},{"recipeId":10035,"title":"Canh Khoai Nấm – bản giữ cân","cookTimeMinutes":23}]}', DATEADD(MINUTE,-17039,@Now)),
(10003, 10001, 'USER', N'Đậu hũ và tempeh khác nhau thế nào?', NULL, DATEADD(MINUTE,-17034,@Now)),
(10004, 10001, 'ASSISTANT', N'Đậu hũ làm từ sữa đậu nành đông tụ, mềm và nhẹ. Tempeh làm từ đậu nành lên men nên đặc, nhiều chất xơ và có vị bùi, thường giàu đạm hơn trên cùng khối lượng. Gợi ý thêm: Rau Luộc Kho Quẹt Chay.', N'{"sources":[{"type":"RECIPE","id":10082,"title":"Rau Luộc Kho Quẹt Chay – bản tăng cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10082,"title":"Rau Luộc Kho Quẹt Chay – bản tăng cân","cookTimeMinutes":33}]}', DATEADD(MINUTE,-17033,@Now)),
(10005, 10001, 'USER', N'Ăn chay trường có được ăn hành tỏi không?', NULL, DATEADD(MINUTE,-17025,@Now)),
(10006, 10001, 'ASSISTANT', N'Theo trường phái Phật giáo, ngũ vị tân (hành, tỏi, hẹ, kiệu, boa-rô) thường được kiêng. Bạn có thể bật tùy chọn không ngũ vị tân để nhận công thức phù hợp.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-17024,@Now)),
(10007, 10001, 'USER', N'Tăng cân khi ăn chay bằng cách nào?', NULL, DATEADD(MINUTE,-17018,@Now)),
