(10019, 10002, 'USER', N'Mình ăn chay thì nên bổ sung đạm từ nguồn nào?', NULL, DATEADD(MINUTE,-16924,@Now)),
(10020, 10002, 'ASSISTANT', N'Bạn có thể lấy đạm từ đậu hũ, tempeh, các loại đậu (đậu nành, đậu lăng, đậu gà), hạt và ngũ cốc nguyên hạt. Kết hợp nhiều nguồn trong ngày giúp đủ các axit amin cần thiết.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-16923,@Now)),
(10021, 10003, 'USER', N'Tăng cân khi ăn chay bằng cách nào?', NULL, DATEADD(MINUTE,-16860,@Now)),
(10022, 10003, 'ASSISTANT', N'Hãy tăng khẩu phần năng lượng bằng các món giàu đạm và chất béo tốt như đậu hũ chiên, tempeh, hạt, khoai lang, kết hợp tập luyện kháng lực và ăn thêm bữa phụ.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-16859,@Now)),
(10023, 10003, 'USER', N'Mình bị dị ứng đậu phộng thì nên tránh món nào?', NULL, DATEADD(MINUTE,-16851,@Now)),
(10024, 10003, 'ASSISTANT', N'Bạn nên tránh các món có đậu phộng rang, bơ đậu phộng, nước chấm có lạc và kiểm tra nhãn sản phẩm. Hãy khai báo dị ứng trong hồ sơ để hệ thống lọc công thức phù hợp.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-16850,@Now)),
(10025, 10003, 'USER', N'Ăn chay trường có được ăn hành tỏi không?', NULL, DATEADD(MINUTE,-16845,@Now)),
(10026, 10003, 'ASSISTANT', N'Theo trường phái Phật giáo, ngũ vị tân (hành, tỏi, hẹ, kiệu, boa-rô) thường được kiêng. Bạn có thể bật tùy chọn không ngũ vị tân để nhận công thức phù hợp.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-16844,@Now)),
(10027, 10003, 'USER', N'Tủ lạnh mình có nấm và cà chua, nấu gì nhanh?', NULL, DATEADD(MINUTE,-16842,@Now)),
(10028, 10003, 'ASSISTANT', N'Bạn có thể nấu canh nấm cà chua hoặc đậu hũ sốt cà chua nấm trong khoảng 15–20 phút, ăn kèm cơm gạo lứt cho đủ chất. Gợi ý thêm: Đậu Phụ Sốt Cay Tứ Xuyên.', N'{"sources":[{"type":"RECIPE","id":10104,"title":"Đậu Phụ Sốt Cay Tứ Xuyên – bản tăng cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10104,"title":"Đậu Phụ Sốt Cay Tứ Xuyên – bản tăng cân","cookTimeMinutes":49}]}', DATEADD(MINUTE,-16841,@Now)),
(10029, 10003, 'USER', N'Gợi ý thực đơn giảm cân cho một ngày ăn chay?', NULL, DATEADD(MINUTE,-16833,@Now)),
(10030, 10003, 'ASSISTANT', N'Bạn có thể ăn sáng với cháo yến mạch rau củ, trưa với cơm gạo lứt và đậu hũ sốt cà chua, tối với canh nấm rau củ. Tổng năng lượng nên bám theo mục tiêu calo trong hồ sơ của bạn.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-16832,@Now)),
