(10100, 10010, 'ASSISTANT', N'Theo trường phái Phật giáo, ngũ vị tân (hành, tỏi, hẹ, kiệu, boa-rô) thường được kiêng. Bạn có thể bật tùy chọn không ngũ vị tân để nhận công thức phù hợp.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-29300,@Now)),
