(10388, 10041, 'ASSISTANT', N'Bạn nên tránh các món có đậu phộng rang, bơ đậu phộng, nước chấm có lạc và kiểm tra nhãn sản phẩm. Hãy khai báo dị ứng trong hồ sơ để hệ thống lọc công thức phù hợp. Gợi ý thêm: Đậu Hũ La Hán.', N'{"sources":[{"type":"RECIPE","id":10058,"title":"Đậu Hũ La Hán – bản giữ cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10058,"title":"Đậu Hũ La Hán – bản giữ cân","cookTimeMinutes":42}]}', DATEADD(MINUTE,-13757,@Now)),
(10389, 10041, 'USER', N'Đậu hũ và tempeh khác nhau thế nào?', NULL, DATEADD(MINUTE,-13756,@Now)),
(10390, 10041, 'ASSISTANT', N'Đậu hũ làm từ sữa đậu nành đông tụ, mềm và nhẹ. Tempeh làm từ đậu nành lên men nên đặc, nhiều chất xơ và có vị bùi, thường giàu đạm hơn trên cùng khối lượng.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-13755,@Now)),
(10391, 10042, 'USER', N'Mình ăn chay thì nên bổ sung đạm từ nguồn nào?', NULL, DATEADD(MINUTE,-24731,@Now)),
(10392, 10042, 'ASSISTANT', N'Bạn có thể lấy đạm từ đậu hũ, tempeh, các loại đậu (đậu nành, đậu lăng, đậu gà), hạt và ngũ cốc nguyên hạt. Kết hợp nhiều nguồn trong ngày giúp đủ các axit amin cần thiết. Gợi ý thêm: Chả Giò Bắp Chay; Nấm Rơm Xào Đậu Phụ.', N'{"sources":[{"type":"RECIPE","id":10068,"title":"Chả Giò Bắp Chay – bản tăng cân"},{"type":"RECIPE","id":10038,"title":"Nấm Rơm Xào Đậu Phụ – bản giữ cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10068,"title":"Chả Giò Bắp Chay – bản tăng cân","cookTimeMinutes":36},{"recipeId":10038,"title":"Nấm Rơm Xào Đậu Phụ – bản giữ cân","cookTimeMinutes":33}]}', DATEADD(MINUTE,-24730,@Now)),
(10393, 10043, 'USER', N'Gợi ý thực đơn giảm cân cho một ngày ăn chay?', NULL, DATEADD(MINUTE,-17981,@Now)),
