(10848, 10093, 'ASSISTANT', N'Đậu hũ làm từ sữa đậu nành đông tụ, mềm và nhẹ. Tempeh làm từ đậu nành lên men nên đặc, nhiều chất xơ và có vị bùi, thường giàu đạm hơn trên cùng khối lượng.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-10922,@Now)),
(10849, 10093, 'USER', N'Tủ lạnh mình có nấm và cà chua, nấu gì nhanh?', NULL, DATEADD(MINUTE,-10917,@Now)),
(10850, 10093, 'ASSISTANT', N'Bạn có thể nấu canh nấm cà chua hoặc đậu hũ sốt cà chua nấm trong khoảng 15–20 phút, ăn kèm cơm gạo lứt cho đủ chất. Gợi ý thêm: Đậu Hủ Nhồi Chay.', N'{"sources":[{"type":"RECIPE","id":10065,"title":"Đậu Hủ Nhồi Chay – bản tăng cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10065,"title":"Đậu Hủ Nhồi Chay – bản tăng cân","cookTimeMinutes":32}]}', DATEADD(MINUTE,-10916,@Now)),
(10851, 10094, 'USER', N'Tăng cân khi ăn chay bằng cách nào?', NULL, DATEADD(MINUTE,-2785,@Now)),
(10852, 10094, 'ASSISTANT', N'Hãy tăng khẩu phần năng lượng bằng các món giàu đạm và chất béo tốt như đậu hũ chiên, tempeh, hạt, khoai lang, kết hợp tập luyện kháng lực và ăn thêm bữa phụ. Gợi ý thêm: Bò Bía Chay; Váng Đậu Xào Chay.', N'{"sources":[{"type":"RECIPE","id":10034,"title":"Bò Bía Chay – bản giữ cân"},{"type":"RECIPE","id":10075,"title":"Váng Đậu Xào Chay – bản giữ cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10034,"title":"Bò Bía Chay – bản giữ cân","cookTimeMinutes":31},{"recipeId":10075,"title":"Váng Đậu Xào Chay – bản giữ cân","cookTimeMinutes":36}]}', DATEADD(MINUTE,-2784,@Now)),
