(11080, 10120, 'ASSISTANT', N'Hãy tăng khẩu phần năng lượng bằng các món giàu đạm và chất béo tốt như đậu hũ chiên, tempeh, hạt, khoai lang, kết hợp tập luyện kháng lực và ăn thêm bữa phụ.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-12248,@Now)),
(11081, 10120, 'USER', N'Mình ăn chay thì nên bổ sung đạm từ nguồn nào?', NULL, DATEADD(MINUTE,-12246,@Now)),
(11082, 10120, 'ASSISTANT', N'Bạn có thể lấy đạm từ đậu hũ, tempeh, các loại đậu (đậu nành, đậu lăng, đậu gà), hạt và ngũ cốc nguyên hạt. Kết hợp nhiều nguồn trong ngày giúp đủ các axit amin cần thiết. Gợi ý thêm: Chả Giò Chay; Bún Thái Chua Cay Chay.', N'{"sources":[{"type":"RECIPE","id":10136,"title":"Chả Giò Chay – bản giảm cân"},{"type":"RECIPE","id":10001,"title":"Bún Thái Chua Cay Chay – bản giảm cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10136,"title":"Chả Giò Chay – bản giảm cân","cookTimeMinutes":42},{"recipeId":10001,"title":"Bún Thái Chua Cay Chay – bản giảm cân","cookTimeMinutes":47}]}', DATEADD(MINUTE,-12245,@Now)),
