(11085, 10120, 'USER', N'Đậu hũ và tempeh khác nhau thế nào?', NULL, DATEADD(MINUTE,-12242,@Now)),
(11086, 10120, 'ASSISTANT', N'Đậu hũ làm từ sữa đậu nành đông tụ, mềm và nhẹ. Tempeh làm từ đậu nành lên men nên đặc, nhiều chất xơ và có vị bùi, thường giàu đạm hơn trên cùng khối lượng. Gợi ý thêm: Cuốn Kho Chay Rong Biển; Bánh Cuốn Chay.', N'{"sources":[{"type":"RECIPE","id":10098,"title":"Cuốn Kho Chay Rong Biển – bản giữ cân"},{"type":"RECIPE","id":10114,"title":"Bánh Cuốn Chay – bản giữ cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10098,"title":"Cuốn Kho Chay Rong Biển – bản giữ cân","cookTimeMinutes":36},{"recipeId":10114,"title":"Bánh Cuốn Chay – bản giữ cân","cookTimeMinutes":32}]}', DATEADD(MINUTE,-12241,@Now)),
