(11136, 10126, 'ASSISTANT', N'Bạn nên tránh các món có đậu phộng rang, bơ đậu phộng, nước chấm có lạc và kiểm tra nhãn sản phẩm. Hãy khai báo dị ứng trong hồ sơ để hệ thống lọc công thức phù hợp. Gợi ý thêm: Đậu Hũ Non Sốt Nấm Đông Cô; Mì Quảng Chay.', N'{"sources":[{"type":"RECIPE","id":10008,"title":"Đậu Hũ Non Sốt Nấm Đông Cô – bản giữ cân"},{"type":"RECIPE","id":10084,"title":"Mì Quảng Chay – bản giữ cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10008,"title":"Đậu Hũ Non Sốt Nấm Đông Cô – bản giữ cân","cookTimeMinutes":36},{"recipeId":10084,"title":"Mì Quảng Chay – bản giữ cân","cookTimeMinutes":48}]}', DATEADD(MINUTE,-13341,@Now)),
(11137, 10127, 'USER', N'Tăng cân khi ăn chay bằng cách nào?', NULL, DATEADD(MINUTE,-594,@Now)),
(11138, 10127, 'ASSISTANT', N'Hãy tăng khẩu phần năng lượng bằng các món giàu đạm và chất béo tốt như đậu hũ chiên, tempeh, hạt, khoai lang, kết hợp tập luyện kháng lực và ăn thêm bữa phụ. Gợi ý thêm: Canh Khoai Nấm.', N'{"sources":[{"type":"RECIPE","id":10035,"title":"Canh Khoai Nấm – bản giữ cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10035,"title":"Canh Khoai Nấm – bản giữ cân","cookTimeMinutes":23}]}', DATEADD(MINUTE,-593,@Now)),
(11139, 10127, 'USER', N'Mình ăn chay thì nên bổ sung đạm từ nguồn nào?', NULL, DATEADD(MINUTE,-592,@Now)),
(11140, 10127, 'ASSISTANT', N'Bạn có thể lấy đạm từ đậu hũ, tempeh, các loại đậu (đậu nành, đậu lăng, đậu gà), hạt và ngũ cốc nguyên hạt. Kết hợp nhiều nguồn trong ngày giúp đủ các axit amin cần thiết.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-591,@Now)),
(11141, 10128, 'USER', N'Đậu hũ và tempeh khác nhau thế nào?', NULL, DATEADD(MINUTE,-13792,@Now)),
(11142, 10128, 'ASSISTANT', N'Đậu hũ làm từ sữa đậu nành đông tụ, mềm và nhẹ. Tempeh làm từ đậu nành lên men nên đặc, nhiều chất xơ và có vị bùi, thường giàu đạm hơn trên cùng khối lượng.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-13791,@Now)),
