(11193, 10131, 'USER', N'Gợi ý thực đơn giảm cân cho một ngày ăn chay?', NULL, DATEADD(MINUTE,-33637,@Now)),
(11194, 10131, 'ASSISTANT', N'Bạn có thể ăn sáng với cháo yến mạch rau củ, trưa với cơm gạo lứt và đậu hũ sốt cà chua, tối với canh nấm rau củ. Tổng năng lượng nên bám theo mục tiêu calo trong hồ sơ của bạn.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-33636,@Now)),
(11195, 10131, 'USER', N'Ăn chay trường có được ăn hành tỏi không?', NULL, DATEADD(MINUTE,-33632,@Now)),
(11196, 10131, 'ASSISTANT', N'Theo trường phái Phật giáo, ngũ vị tân (hành, tỏi, hẹ, kiệu, boa-rô) thường được kiêng. Bạn có thể bật tùy chọn không ngũ vị tân để nhận công thức phù hợp. Gợi ý thêm: Đậu Bắp Kho Nước Tương.', N'{"sources":[{"type":"RECIPE","id":10109,"title":"Đậu Bắp Kho Nước Tương – bản tăng cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10109,"title":"Đậu Bắp Kho Nước Tương – bản tăng cân","cookTimeMinutes":32}]}', DATEADD(MINUTE,-33631,@Now)),
