(11466, 10160, 'ASSISTANT', N'Theo trường phái Phật giáo, ngũ vị tân (hành, tỏi, hẹ, kiệu, boa-rô) thường được kiêng. Bạn có thể bật tùy chọn không ngũ vị tân để nhận công thức phù hợp. Gợi ý thêm: Miến Xào Với Mít Non; Cuốn Chay.', N'{"sources":[{"type":"RECIPE","id":10182,"title":"Miến Xào Với Mít Non – bản tăng cân (không hành tỏi)"},{"type":"RECIPE","id":10143,"title":"Cuốn Chay – bản tăng cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10182,"title":"Miến Xào Với Mít Non – bản tăng cân (không hành tỏi)","cookTimeMinutes":26},{"recipeId":10143,"title":"Cuốn Chay – bản tăng cân","cookTimeMinutes":26}]}', DATEADD(MINUTE,-19990,@Now)),
(11467, 10160, 'USER', N'Tăng cân khi ăn chay bằng cách nào?', NULL, DATEADD(MINUTE,-19984,@Now)),
(11468, 10160, 'ASSISTANT', N'Hãy tăng khẩu phần năng lượng bằng các món giàu đạm và chất béo tốt như đậu hũ chiên, tempeh, hạt, khoai lang, kết hợp tập luyện kháng lực và ăn thêm bữa phụ. Gợi ý thêm: Đậu Bắp Kho Nước Tương.', N'{"sources":[{"type":"RECIPE","id":10109,"title":"Đậu Bắp Kho Nước Tương – bản tăng cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10109,"title":"Đậu Bắp Kho Nước Tương – bản tăng cân","cookTimeMinutes":32}]}', DATEADD(MINUTE,-19983,@Now)),
(11469, 10160, 'USER', N'Mình bị dị ứng đậu phộng thì nên tránh món nào?', NULL, DATEADD(MINUTE,-19978,@Now)),
(11470, 10160, 'ASSISTANT', N'Bạn nên tránh các món có đậu phộng rang, bơ đậu phộng, nước chấm có lạc và kiểm tra nhãn sản phẩm. Hãy khai báo dị ứng trong hồ sơ để hệ thống lọc công thức phù hợp. Gợi ý thêm: Rau Luộc Kho Quẹt Chay; Bún Trộn Dưa Leo.', N'{"sources":[{"type":"RECIPE","id":10082,"title":"Rau Luộc Kho Quẹt Chay – bản tăng cân"},{"type":"RECIPE","id":10172,"title":"Bún Trộn Dưa Leo – bản giảm cân (không hành tỏi)"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10082,"title":"Rau Luộc Kho Quẹt Chay – bản tăng cân","cookTimeMinutes":33},{"recipeId":10172,"title":"Bún Trộn Dưa Leo – bản giảm cân (không hành tỏi)","cookTimeMinutes":39}]}', DATEADD(MINUTE,-19977,@Now)),
(11471, 10160, 'USER', N'Tăng cân khi ăn chay bằng cách nào?', NULL, DATEADD(MINUTE,-19969,@Now)),
