(11473, 10160, 'USER', N'Gợi ý thực đơn giảm cân cho một ngày ăn chay?', NULL, DATEADD(MINUTE,-19963,@Now)),
(11474, 10160, 'ASSISTANT', N'Bạn có thể ăn sáng với cháo yến mạch rau củ, trưa với cơm gạo lứt và đậu hũ sốt cà chua, tối với canh nấm rau củ. Tổng năng lượng nên bám theo mục tiêu calo trong hồ sơ của bạn. Gợi ý thêm: Bánh Cuốn Chay; Cơm Cuộn Chay.', N'{"sources":[{"type":"RECIPE","id":10114,"title":"Bánh Cuốn Chay – bản giữ cân"},{"type":"RECIPE","id":10096,"title":"Cơm Cuộn Chay – bản giữ cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10114,"title":"Bánh Cuốn Chay – bản giữ cân","cookTimeMinutes":32},{"recipeId":10096,"title":"Cơm Cuộn Chay – bản giữ cân","cookTimeMinutes":64}]}', DATEADD(MINUTE,-19962,@Now)),
