(11576, 10169, 'ASSISTANT', N'Bạn có thể ăn sáng với cháo yến mạch rau củ, trưa với cơm gạo lứt và đậu hũ sốt cà chua, tối với canh nấm rau củ. Tổng năng lượng nên bám theo mục tiêu calo trong hồ sơ của bạn.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-3177,@Now)),
(11577, 10170, 'USER', N'Tủ lạnh mình có nấm và cà chua, nấu gì nhanh?', NULL, DATEADD(MINUTE,-20348,@Now)),
(11578, 10170, 'ASSISTANT', N'Bạn có thể nấu canh nấm cà chua hoặc đậu hũ sốt cà chua nấm trong khoảng 15–20 phút, ăn kèm cơm gạo lứt cho đủ chất.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-20347,@Now)),
(11579, 10170, 'USER', N'Gợi ý thực đơn giảm cân cho một ngày ăn chay?', NULL, DATEADD(MINUTE,-20342,@Now)),
