(11939, 10208, 'USER', N'Mình ăn chay thì nên bổ sung đạm từ nguồn nào?', NULL, DATEADD(MINUTE,-10616,@Now)),
(11940, 10208, 'ASSISTANT', N'Bạn có thể lấy đạm từ đậu hũ, tempeh, các loại đậu (đậu nành, đậu lăng, đậu gà), hạt và ngũ cốc nguyên hạt. Kết hợp nhiều nguồn trong ngày giúp đủ các axit amin cần thiết. Gợi ý thêm: Rau Củ Xào Thập Cẩm.', N'{"sources":[{"type":"RECIPE","id":10044,"title":"Rau Củ Xào Thập Cẩm – bản giảm cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10044,"title":"Rau Củ Xào Thập Cẩm – bản giảm cân","cookTimeMinutes":29}]}', DATEADD(MINUTE,-10615,@Now)),
(11941, 10208, 'USER', N'Ăn chay trường có được ăn hành tỏi không?', NULL, DATEADD(MINUTE,-10611,@Now)),
(11942, 10208, 'ASSISTANT', N'Theo trường phái Phật giáo, ngũ vị tân (hành, tỏi, hẹ, kiệu, boa-rô) thường được kiêng. Bạn có thể bật tùy chọn không ngũ vị tân để nhận công thức phù hợp. Gợi ý thêm: Rau Củ Luộc Chấm Nấm Đông Cô Kho Quẹt Chay; Miến Xào Với Mít Non.', N'{"sources":[{"type":"RECIPE","id":10074,"title":"Rau Củ Luộc Chấm Nấm Đông Cô Kho Quẹt Chay – bản giảm cân"},{"type":"RECIPE","id":10055,"title":"Miến Xào Với Mít Non – bản giữ cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10074,"title":"Rau Củ Luộc Chấm Nấm Đông Cô Kho Quẹt Chay – bản giảm cân","cookTimeMinutes":36},{"recipeId":10055,"title":"Miến Xào Với Mít Non – bản giữ cân","cookTimeMinutes":26}]}', DATEADD(MINUTE,-10610,@Now)),
(11943, 10208, 'USER', N'Tăng cân khi ăn chay bằng cách nào?', NULL, DATEADD(MINUTE,-10605,@Now)),
(11944, 10208, 'ASSISTANT', N'Hãy tăng khẩu phần năng lượng bằng các món giàu đạm và chất béo tốt như đậu hũ chiên, tempeh, hạt, khoai lang, kết hợp tập luyện kháng lực và ăn thêm bữa phụ.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-10604,@Now)),
