(11948, 10208, 'ASSISTANT', N'Bạn có thể ăn sáng với cháo yến mạch rau củ, trưa với cơm gạo lứt và đậu hũ sốt cà chua, tối với canh nấm rau củ. Tổng năng lượng nên bám theo mục tiêu calo trong hồ sơ của bạn.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-10593,@Now)),
(11949, 10208, 'USER', N'Mình bị dị ứng đậu phộng thì nên tránh món nào?', NULL, DATEADD(MINUTE,-10592,@Now)),
(11950, 10208, 'ASSISTANT', N'Bạn nên tránh các món có đậu phộng rang, bơ đậu phộng, nước chấm có lạc và kiểm tra nhãn sản phẩm. Hãy khai báo dị ứng trong hồ sơ để hệ thống lọc công thức phù hợp. Gợi ý thêm: Bún Chay Huế; Cà Tím Kho Đậu Hủ.', N'{"sources":[{"type":"RECIPE","id":10078,"title":"Bún Chay Huế – bản giảm cân"},{"type":"RECIPE","id":10111,"title":"Cà Tím Kho Đậu Hủ – bản giảm cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10078,"title":"Bún Chay Huế – bản giảm cân","cookTimeMinutes":42},{"recipeId":10111,"title":"Cà Tím Kho Đậu Hủ – bản giảm cân","cookTimeMinutes":36}]}', DATEADD(MINUTE,-10591,@Now)),
