(12226, 10238, 'ASSISTANT', N'Hãy tăng khẩu phần năng lượng bằng các món giàu đạm và chất béo tốt như đậu hũ chiên, tempeh, hạt, khoai lang, kết hợp tập luyện kháng lực và ăn thêm bữa phụ.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-23819,@Now)),
(12227, 10238, 'USER', N'Tủ lạnh mình có nấm và cà chua, nấu gì nhanh?', NULL, DATEADD(MINUTE,-23815,@Now)),
(12228, 10238, 'ASSISTANT', N'Bạn có thể nấu canh nấm cà chua hoặc đậu hũ sốt cà chua nấm trong khoảng 15–20 phút, ăn kèm cơm gạo lứt cho đủ chất.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-23814,@Now)),
(12229, 10238, 'USER', N'Mình bị dị ứng đậu phộng thì nên tránh món nào?', NULL, DATEADD(MINUTE,-23812,@Now)),
(12230, 10238, 'ASSISTANT', N'Bạn nên tránh các món có đậu phộng rang, bơ đậu phộng, nước chấm có lạc và kiểm tra nhãn sản phẩm. Hãy khai báo dị ứng trong hồ sơ để hệ thống lọc công thức phù hợp.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-23811,@Now)),
(12231, 10238, 'USER', N'Gợi ý thực đơn giảm cân cho một ngày ăn chay?', NULL, DATEADD(MINUTE,-23809,@Now)),
(12232, 10238, 'ASSISTANT', N'Bạn có thể ăn sáng với cháo yến mạch rau củ, trưa với cơm gạo lứt và đậu hũ sốt cà chua, tối với canh nấm rau củ. Tổng năng lượng nên bám theo mục tiêu calo trong hồ sơ của bạn.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-23808,@Now)),
(12233, 10239, 'USER', N'Mình ăn chay thì nên bổ sung đạm từ nguồn nào?', NULL, DATEADD(MINUTE,-15477,@Now)),
(12234, 10239, 'ASSISTANT', N'Bạn có thể lấy đạm từ đậu hũ, tempeh, các loại đậu (đậu nành, đậu lăng, đậu gà), hạt và ngũ cốc nguyên hạt. Kết hợp nhiều nguồn trong ngày giúp đủ các axit amin cần thiết.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-15476,@Now)),
(12235, 10240, 'USER', N'Mình ăn chay thì nên bổ sung đạm từ nguồn nào?', NULL, DATEADD(MINUTE,-2078,@Now)),
(12236, 10240, 'ASSISTANT', N'Bạn có thể lấy đạm từ đậu hũ, tempeh, các loại đậu (đậu nành, đậu lăng, đậu gà), hạt và ngũ cốc nguyên hạt. Kết hợp nhiều nguồn trong ngày giúp đủ các axit amin cần thiết. Gợi ý thêm: Đậu Xào Rau Củ; Bún Thái Chua Cay Chay.', N'{"sources":[{"type":"RECIPE","id":10156,"title":"Đậu Xào Rau Củ – bản giữ cân (không hành tỏi)"},{"type":"RECIPE","id":10001,"title":"Bún Thái Chua Cay Chay – bản giảm cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10156,"title":"Đậu Xào Rau Củ – bản giữ cân (không hành tỏi)","cookTimeMinutes":33},{"recipeId":10001,"title":"Bún Thái Chua Cay Chay – bản giảm cân","cookTimeMinutes":47}]}', DATEADD(MINUTE,-2077,@Now));
